func (s MapVals) JSONSize() int {
	size := 75
	size += len(s.Anys) * 68
	for k := range s.Anys {
		size += len(k) * 2
	}
	size += len(s.Blobs) * 4
	for k, v := range s.Blobs {
		size += len(k) * 2
		size += 4
		size += ((len(v) + 2) / 3) * 4
	}
	size += len(s.Durs) * 31
	for k := range s.Durs {
		size += len(k) * 2
	}
	size += len(s.Ints) * 4
	for k, v := range s.Ints {
		size += len(k) * 2
		size += 4
		if n := len(v); n > 0 {
			size += n - 1
		}
		size += len(v) * 20
	}
	size += len(s.Raws) * 4
	for k, v := range s.Raws {
		size += len(k) * 2
		if n := len(v); n > 0 {
			size += n
		} else {
			size += 4
		}
	}
	size += len(s.Times) * 41
	for k := range s.Times {
		size += len(k) * 2
	}
	return size
}

